/* ---------- drawings with colors, shade and detail ----------
   Clothes (man, woman, baby), house, kitchen, eye, mouth and ear. They use the same engine as the body drawings (js/bodydiagram.js,
   renderDiagramSet): numbered, tappable parts that find their word by its Greek text, a list of words next to the drawing.
   The difference: every shape brings its own colors (the "style" of each shape, made by the helpers below), and the drawing has "rich":true.
   Write a path with absolute commands M L C Q Z and "x,y" pairs: SC.mir() then flips it left/right around the middle line (x = 150).
   A part is {gr, z, dot:[x,y], shapes:[...]}. "defs" of a drawing (gradients) go in its "under". */
const SC = {
  line:"#3a2c27",
  /* a gradient: SC.g("id", top color, bottom color [, "h" for left to right]) */
  g:(id,a,b,dir)=>`<linearGradient id="${id}" x1="0" y1="0" x2="${dir==="h"?1:0}" y2="${dir==="h"?0:1}"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`,
  /* the same gradient from the center outward (a ball, an eye) */
  rg:(id,a,b)=>`<radialGradient id="${id}" cx=".4" cy=".35" r=".75"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></radialGradient>`,
  st:(fill,o={})=>`fill:${fill};stroke:${o.s||SC.line};stroke-width:${o.w??1.5};stroke-linejoin:round;stroke-linecap:round;${o.x||""}`,
  /* a solid shape also gets a soft light (top left) and shade (bottom right) of its own: it looks round, like a real object. Not for lines, details (w:0), glass (rgba) or tiny shapes. */
  shade:(fill,o,small)=>fill && fill!=="none" && !small && !(o && (o.w===0 || o.sh===false)) && !/^(url|rgba|transparent)/.test(fill),
  lit:`style="fill:url(#scGshade);stroke:none;pointer-events:none"`,
  p:(d,fill,o)=>`<path d="${d}" style="${SC.st(fill,o)}"/>` + (SC.shade(fill,o) ? `<path d="${d}" ${SC.lit}/>` : ""),
  e:(cx,cy,rx,ry,fill,o)=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" style="${SC.st(fill,o)}"/>` + (SC.shade(fill,o,rx<3.2 && ry<3.2) ? `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" ${SC.lit}/>` : ""),
  r:(x,y,w,h,rad,fill,o)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rad}" style="${SC.st(fill,o)}"/>` + (SC.shade(fill,o,w<5 || h<5) ? `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rad}" ${SC.lit}/>` : ""),
  /* a thin line without fill: a fold, a seam, a stitch */
  l:(d,o={})=>`<path d="${d}" style="fill:none;stroke:${o.s||"rgba(0,0,0,.32)"};stroke-width:${o.w??1.1};stroke-linecap:round;stroke-linejoin:round;${o.dash?`stroke-dasharray:${o.dash};`:""}"/>`,
  /* a soft light or shadow spot (no outline) */
  sh:(d,fill)=>`<path d="${d}" style="fill:${fill};stroke:none"/>`,
  mir:d=>d.replace(/(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/g,(m,x,y)=>`${+(300-x).toFixed(1)},${y}`),
  /* a shape and its mirror image (both sleeves, both legs) */
  both:(d,fill,o)=>SC.p(d,fill,o)+SC.p(SC.mir(d),fill,o),
  bothl:(d,o)=>SC.l(d,o)+SC.l(SC.mir(d),o),
  skin:"url(#sk)", skinDef:null
};
SC.skinDef = SC.g("sk","#F8D9C0","#E6B292") + SC.g("skh","#F8D9C0","#E0A987","h");
/* the ids of the gradients are global in the page: each drawing gets its own prefix, so two drawings never share a name (the skin "sk" is the same everywhere) */
SC.scope = (d, pre) => {
  const f = s => s.replace(/id="(?!sk")([^"]+)"/g, `id="${pre}-$1"`).replace(/url\(#(?!sk\)|scG)([^)]+)\)/g, `url(#${pre}-$1)`);
  d.under = f(d.under); d.parts.forEach(q=>{ q.shapes = q.shapes.map(f); });
  return d;
};

