/* ----- the drawings of the page "City & travel": next to the map ----- */
const TRANSPORT_DIAGRAMS = [SC.scope(SC_STREET,"street"), SC.scope(SC_CAR,"car"), SC.scope(SC_CAR_FRONT,"carf"), SC.scope(SC_PLANE,"plane")];
let transportDiagramId = "street", cityHubMode = "map";
const renderTransportDiagram = box => renderDiagramSet(box, TRANSPORT_DIAGRAMS, ()=>transportDiagramId, id=>{ transportDiagramId = id; });
/* the diagram mode of the city has two parts: the map, and the drawings (street, car, plane) */
function renderCityHub(box){
  box.innerHTML = `<div class="row" role="group"><button type="button" class="chip" data-mode="hub-map" data-hub="map" aria-pressed="${cityHubMode==="map"}">${esc(tx("Map"))}</button><button type="button" class="chip" data-mode="hub-draw" data-hub="draw" aria-pressed="${cityHubMode==="draw"}">${esc(tx("Drawings"))}</button></div><div class="hub-body"></div>`;
  const body = box.querySelector(".hub-body");
  const show = ()=>{ box.querySelectorAll("[data-hub]").forEach(b=>b.setAttribute("aria-pressed", b.dataset.hub===cityHubMode)); body.innerHTML = ""; (cityHubMode==="map" ? renderMap : renderTransportDiagram)(body); };
  box.querySelectorAll("[data-hub]").forEach(b=>b.onclick = ()=>{ cityHubMode = b.dataset.hub; show(); });
  show();
}

/* ======================= FAMILY: a family tree ======================= */
const SC_FAMILY = (()=>{
  const {p,e,r,l,sh,g} = SC;
  const defs = SC.skinDef + g("bgf","#F1F8E4","#DDEBC4") + g("ring","#FFFFFF","#EFE7D6");
  /* a person in a round frame: cx, cy = center; o = {bg, shirt, hair, style:"short|long|bald|bun|curl|baby|grey", s: size, glasses} */
  const person = (cx,cy,o)=>{
    const s = o.s || 1, hy = cy-5*s, hr = 14*s;
    const hairBack = o.style==="long" ? p(`M${cx-hr-3},${hy} C${cx-hr-5},${hy+26*s} ${cx-hr},${cy+26*s} ${cx-hr+4},${cy+28*s} L${cx+hr-4},${cy+28*s} C${cx+hr},${cy+26*s} ${cx+hr+5},${hy+26*s} ${cx+hr+3},${hy}Z`, o.hair) : "";
    const hair = {
      short:  p(`M${cx-hr},${hy-1} C${cx-hr},${hy-hr-3} ${cx+hr},${hy-hr-3} ${cx+hr},${hy-1} C${cx+hr-3},${hy-8*s} ${cx-hr+3},${hy-8*s} ${cx-hr},${hy-1}Z`, o.hair),
      long:   p(`M${cx-hr},${hy+1} C${cx-hr-1},${hy-hr-3} ${cx+hr+1},${hy-hr-3} ${cx+hr},${hy+1} C${cx+hr-2},${hy-9*s} ${cx-hr+2},${hy-9*s} ${cx-hr},${hy+1}Z`, o.hair),
      bald:   "",
      grey:   p(`M${cx-hr},${hy} C${cx-hr-1},${hy-hr-2} ${cx+hr+1},${hy-hr-2} ${cx+hr},${hy} C${cx+hr-3},${hy-7*s} ${cx-hr+3},${hy-7*s} ${cx-hr},${hy}Z`, "#E4E4E4"),
      bun:    p(`M${cx-hr},${hy} C${cx-hr},${hy-hr-2} ${cx+hr},${hy-hr-2} ${cx+hr},${hy} C${cx+hr-3},${hy-7*s} ${cx-hr+3},${hy-7*s} ${cx-hr},${hy}Z`, "#E4E4E4") + e(cx,hy-hr-3*s,6*s,5*s,"#E4E4E4"),
      curl:   [-10,-5,0,5,10].map(dx=>e(cx+dx*s,hy-hr+3*s+Math.abs(dx)*.2,5.4*s,5.4*s,o.hair)).join(""),
      baby:   p(`M${cx-3},${hy-hr} C${cx-2},${hy-hr-6} ${cx+4},${hy-hr-6} ${cx+3},${hy-hr+2}`,"none",{w:2,s:o.hair})
    }[o.style||"short"];
    const eyes = e(cx-5*s,hy+1,1.7*s,1.9*s,"#2A1F1B",{w:0}) + e(cx+5*s,hy+1,1.7*s,1.9*s,"#2A1F1B",{w:0}) + p(`M${cx-4.5*s},${hy+8*s} Q${cx},${hy+11*s} ${cx+4.5*s},${hy+8*s}`,"none",{w:1.3,s:"#9C4A3F"});
    const gl = o.glasses ? e(cx-5*s,hy+1,4.6*s,4.2*s,"none",{w:1.3,s:"#2A2A33"}) + e(cx+5*s,hy+1,4.6*s,4.2*s,"none",{w:1.3,s:"#2A2A33"}) + p(`M${cx-.6*s},${hy+1} L${cx+.6*s},${hy+1}`,"none",{w:1.2,s:"#2A2A33"}) : "";
    const cid = "cp"+Math.round(cx)+"-"+Math.round(cy);
    return `<clipPath id="${cid}"><circle cx="${cx}" cy="${cy}" r="${34*s}"/></clipPath>` + e(cx,cy,34*s,34*s,o.bg,{w:0}) +
      `<g clip-path="url(#${cid})">` + hairBack +
      p(`M${cx-24*s},${cy+36*s} C${cx-24*s},${cy+14*s} ${cx-12*s},${cy+8*s} ${cx},${cy+8*s} C${cx+12*s},${cy+8*s} ${cx+24*s},${cy+14*s} ${cx+24*s},${cy+36*s}Z`, o.shirt) +
      p(`M${cx-4*s},${cy+8*s} L${cx},${cy+14*s} L${cx+4*s},${cy+8*s}Z`,"url(#sk)",{w:1}) +
      e(cx,hy,hr,hr*1.08,"url(#sk)",{w:1.5}) + hair + eyes + gl + `</g>` + e(cx,cy,34*s,34*s,"none",{w:2.4,s:"#8A6A3E"});
  };
  const P = (gr,z,dot,list)=>({gr,z,dot,shapes:[list.map(([x,y,o])=>person(x,y,o)).join("")]});
  const under = defs + r(0,0,400,400,0,"url(#bgf)",{w:0}) +
    /* the branches of the tree: lines between the generations */
    [ "M90,60 L90,114 M50,114 L140,114 M50,114 L50,170 M140,114 L140,170",
      "M310,60 L310,114 M260,114 L350,114 M260,114 L260,170 M350,114 L350,170",
      "M200,170 L200,236 M130,236 L270,236 M130,236 L130,290 M200,236 L200,290 M270,236 L270,290",
      "M50,170 L50,290", "M350,170 L350,290", "M200,290 L200,352" ].map(d=>p(d,"none",{w:5,s:"#9A7248"})).join("") +
    l("M174,170 L226,170",{s:"#C0392B",w:3}) + p("M200,178 C188,168 194,160 200,166 C206,160 212,168 200,178Z","#E8433F",{w:1});
  const gp = {bg:"#FBE9C6", shirt:"#7A8FB0", hair:"#E4E4E4", style:"grey", glasses:true};
  const parts = [
    P("ο παππούς", 2, [79,84], [[55,60,{...gp,style:"bald",shirt:"#6B8E7A"}],[275,60,{...gp,shirt:"#8A6A3E"}]]),
    P("η γιαγιά", 2, [149,84], [[125,60,{bg:"#FBE0E6",shirt:"#B8668A",hair:"#E4E4E4",style:"bun"}],[345,60,{bg:"#FBE0E6",shirt:"#7A6AB0",hair:"#E4E4E4",style:"bun",glasses:true}]]),
    P("ο μπαμπάς", 2, [164,194], [[140,170,{bg:"#D9ECF8",shirt:"#3E6FB0",hair:"#4A3426",style:"short"}]]),
    P("η μαμά", 2, [284,194], [[260,170,{bg:"#FBE0E6",shirt:"#D8607A",hair:"#6A3A26",style:"long"}]]),
    P("ο θείος", 2, [74,194], [[50,170,{bg:"#E1F3DC",shirt:"#4E8E58",hair:"#2A1F1B",style:"curl"}]]),
    P("η θεία", 2, [374,194], [[350,170,{bg:"#FFF1CC",shirt:"#E0A030",hair:"#B0562A",style:"long"}]]),
    P("ο ξάδερφος", 2, [72,312], [[50,290,{bg:"#E1F3DC",shirt:"#7FB36A",hair:"#2A1F1B",style:"short",s:.9}]]),
    P("η ξαδέρφη", 2, [372,312], [[350,290,{bg:"#FFF1CC",shirt:"#F0B24A",hair:"#B0562A",style:"long",s:.9}]]),
    P("ο αδερφός", 2, [152,312], [[130,290,{bg:"#D9ECF8",shirt:"#6FA0D8",hair:"#4A3426",style:"short",s:.9}]]),
    P("εγώ", 3, [222,314], [[200,290,{bg:"#FFE0C2",shirt:"#E8776A",hair:"#2A1F1B",style:"short",s:.95}]]),
    P("η αδερφή", 2, [292,312], [[270,290,{bg:"#FBE0E6",shirt:"#E58AA8",hair:"#6A3A26",style:"long",s:.9}]]),
    P("ο γιος", 2, [218,370], [[200,352,{bg:"#FFE0C2",shirt:"#8CC4A8",hair:"#4A3426",style:"short",s:.72}]])
  ];
  return {id:"tree", name:"Family tree", viewBox:"0 0 400 400", rich:true, under, parts};
})();

