/* ======================= NUMBERS: counting cards and the tens ======================= */
const SC_COUNT = (()=>{
  const {p,e,r,l,sh,g} = SC;
  const PAL = [["#E3F1FB","#BCDCF2"],["#FFF1C2","#F6D56E"],["#E7F6E1","#C6E5B8"],["#FBE5EE","#F2BFD3"],["#EEE6F8","#D5C6EE"],["#FFE8D6","#F8C9A6"]];
  const defs = PAL.map(([a,b],i)=>g("c"+i,a,b)).join("");
  const heart = (x,y,s,c)=> p(`M${x},${y+s*.9} C${x-s*1.3},${y-s*.1} ${x-s*.5},${y-s*.9} ${x},${y-s*.3} C${x+s*.5},${y-s*.9} ${x+s*1.3},${y-s*.1} ${x},${y+s*.9}Z`,c,{w:1.1,s:"rgba(0,0,0,.4)"});
  const star = (x,y,R,c)=>{ const pts=[]; for(let i=0;i<10;i++){ const rad = i%2 ? R*.45 : R, a = -Math.PI/2 + i*Math.PI/5; pts.push(`${(x+rad*Math.cos(a)).toFixed(1)},${(y+rad*Math.sin(a)).toFixed(1)}`); } return p("M"+pts.join(" L")+"Z",c,{w:1.1,s:"rgba(0,0,0,.4)"}); };
  const SHAPES = [
    (x,y,c)=>e(x,y,7,7,c,{w:1.1,s:"rgba(0,0,0,.4)"}), (x,y,c)=>heart(x,y,7,c), (x,y,c)=>star(x,y,8.5,c), (x,y,c)=>r(x-6.5,y-6.5,13,13,2,c,{w:1.1,s:"rgba(0,0,0,.4)"}),
    (x,y,c)=>p(`M${x},${y-8} L${x+8},${y+6} L${x-8},${y+6}Z`,c,{w:1.1,s:"rgba(0,0,0,.4)"}), (x,y,c)=>p(`M${x},${y-8} C${x+9},${y+2} ${x+6},${y+8} ${x},${y+8} C${x-6},${y+8} ${x-9},${y+2} ${x},${y-8}Z`,c,{w:1.1,s:"rgba(0,0,0,.4)"})
  ];
  const COL = ["#E8433F","#3E7BD1","#F2A22E","#3FA66A","#8A55C8","#E8579A"];
  const NAMES = ["μηδέν","ένα","δύο","τρία","τέσσερα","πέντε","έξι","εφτά","οχτώ","εννιά","δέκα","έντεκα"];
  const parts = NAMES.map((gr,n)=>{
    const c = n%4, rw = Math.floor(n/4), x = 6+c*104, y = 6+rw*108;
    let sh = r(x,y,98,102,12,`url(#c${n%6})`,{w:1.8,s:"#8A9BB0"}) + `<text x="${x+12}" y="${y+30}" style="fill:#2A2E36;stroke:none;font:800 28px 'Commissioner',sans-serif">${n}</text>`;
    for(let i=0;i<n;i++){ const per = n>8 ? 4 : n>4 ? 3 : 3, col = i%per, row = Math.floor(i/per); sh += SHAPES[n%6](x+26+col*22+(n>8?0:0), y+54+row*18, COL[(n+Math.floor(i/2))%6]); }
    return {gr, z:1, dot:[x+86,y+14], shapes:[sh]};
  });
  return {id:"count", name:"Counting", viewBox:"0 0 420 330", rich:true, under:defs, parts};
})();

const SC_TENS = (()=>{
  const {p,e,r,l,sh,g} = SC;
  const defs = g("bg","#FBF8EE","#F1EBD6");
  const COL = ["#E8433F","#F2A22E","#F6D13F","#4CAF50","#3E9BD0","#3E7BD1","#7A55C8","#E8579A","#8A5E33","#2E4A6B"];
  const NAMES = ["δέκα","είκοσι","τριάντα","σαράντα","πενήντα","εξήντα","εβδομήντα","ογδόντα","ενενήντα","εκατό"];
  const parts = NAMES.map((gr,k)=>{
    const y = 8+k*29;
    let sh = "";
    for(let i=0;i<=k;i++) sh += r(40+i*33,y,31,25,4,COL[k],{w:1.4,s:"rgba(0,0,0,.45)"}) + l(`M${44+i*33},${y+6} L${64+i*33},${y+6}`,{s:"rgba(255,255,255,.4)",w:2});
    sh += `<text x="8" y="${y+19}" style="fill:#2A2E36;stroke:none;font:800 16px 'Commissioner',sans-serif">${(k+1)*10}</text>`;
    return {gr, z:1, dot:[404,y+12], shapes:[sh]};
  });
  return {id:"tens", name:"The tens", viewBox:"0 0 420 300", rich:true, under:defs + r(0,0,420,300,0,"url(#bg)",{w:0}), parts};
})();

