    p("M330,250 L396,284","none",{w:7,s:"#8A5E33"}) + p("M392,282 L412,292 L408,276Z","#2A2E36",{w:1.4}) ;
  const POS = [[110,98],[158,66],[214,52],[268,56],[320,76],[352,118],[362,166],[330,208],[274,224],[220,206],[164,170],[198,142],[252,128],[300,148],[300,106],[236,96],[172,116],[116,130]];
