const SC_CASES = (()=>{
  const {p,e,r,l,sh,g} = SC;
  const defs = g("hm","#BCDCF2","#8FB6DE") + g("hf","#F5C2D4","#E89AB6") + g("hn","#C6E5B8","#98CC84") + g("c1","#FFF6D6","#F6E4A8") + g("c2","#FFE6D0","#F8CBA6") + g("c3","#EADFF8","#CDB8EC") + g("c4","#DDF1EE","#B0DCD3");
  const txt = (x,y,s,t,c,wt)=>`<text x="${x}" y="${y}" text-anchor="middle" style="fill:${c||"#2A2E36"};stroke:none;font:${wt||800} ${s}px 'Commissioner',sans-serif">${t}</text>`;
  const COLX = [102,208,314], ROWY = [50,112,174,236];
  const ROWS = [["η ονομαστική","subject","c1"],["η αιτιατική","object","c2"],["η γενική","of","c3"],["η κλητική","calling","c4"]];
  const under = defs + r(0,0,440,300,0,"#FBF8EE",{w:0}) +
    [["ο","hm"],["η","hf"],["το","hn"]].map(([a,id],i)=>r(COLX[i],4,100,40,10,`url(#${id})`,{w:1.6,s:"#7A8BA0"}) + txt(COLX[i]+50,32,24,a)).join("") +
    ROWS.map(([gr,en,id],i)=>r(4,ROWY[i],94,56,10,`url(#${id})`,{w:1.6,s:"#9A8A6A"}) + txt(51,ROWY[i]+26,13,gr) + txt(51,ROWY[i]+44,11,en,"#5A5F6B",600)).join("");
  const FORMS = [
    ["ο φίλος","τον φίλο","του φίλου","φίλε"],
    ["η φίλη","τη φίλη","της φίλης","φίλη"],
    ["το παιδί","το παιδί","του παιδιού","παιδί"]
  ];
  const cell = (c,rw,t)=> r(COLX[c],ROWY[rw],100,56,10,`url(#${["c1","c2","c3","c4"][rw]})`,{w:1.6,s:"#9A8A6A"}) + txt(COLX[c]+50,ROWY[rw]+34,t.length>8?15:17,t);
  const byGr = new Map();
  FORMS.forEach((col,c)=>col.forEach((t,rw)=>{ if(!byGr.has(t)) byGr.set(t,[]); byGr.get(t).push([c,rw]); }));
  const parts = [...byGr.entries()].map(([gr,cells])=>({gr, z:1, dot:[COLX[cells[0][0]]+88, ROWY[cells[0][1]]+10], shapes:[cells.map(([c,rw])=>cell(c,rw,gr)).join("")]}));
  return {id:"cases", name:"The cases", viewBox:"0 0 440 296", rich:true, under, parts};
})();

