const SC_QUESTIONS = (()=>{
  const {p,e,r,l,sh,g} = SC;
  const PAL = [["#FFF1C2","#F6D56E"],["#E3F1FB","#BCDCF2"],["#E7F6E1","#C6E5B8"],["#FBE5EE","#F2BFD3"],["#EEE6F8","#D5C6EE"],["#FFE8D6","#F8C9A6"],["#DDF1EE","#B0DCD3"],["#F4F0E4","#E4DCC4"]];
  const defs = PAL.map(([a,b],i)=>g("q"+i,a,b)).join("");
  const txt = (x,y,s,t,c)=>`<text x="${x}" y="${y}" text-anchor="middle" style="fill:${c||"#2A2E36"};stroke:none;font:800 ${s}px 'Commissioner',sans-serif">${t}</text>`;
  const ICONS = {
    "τι": (cx,cy)=> r(cx-20,cy-14,40,32,3,"#C99A66",{w:1.6,s:"#5A3A1E"}) + r(cx-24,cy-22,48,12,3,"#E0B67A",{w:1.6,s:"#5A3A1E"}) + txt(cx,cy+10,24,"?","#FFFFFF"),
    "ποιος": (cx,cy)=> e(cx,cy-8,12,13,"#F4C9A8",{w:1.6}) + p(`M${cx-22},${cy+22} C${cx-22},${cy+4} ${cx+22},${cy+4} ${cx+22},${cy+22}Z`,"#3E7BD1",{w:1.6}) + txt(cx+22,cy-8,22,"?","#E8433F"),
    "πού": (cx,cy)=> p(`M${cx},${cy+24} C${cx-26},${cy-2} ${cx-22},${cy-26} ${cx},${cy-26} C${cx+22},${cy-26} ${cx+26},${cy-2} ${cx},${cy+24}Z`,"#E8433F",{w:1.8,s:"#7A1E1A"}) + e(cx,cy-8,8,8,"#FFFFFF",{w:1.2,s:"#7A1E1A"}),
    "πότε": (cx,cy)=> e(cx,cy,24,24,"#FFFFFF",{w:2,s:"#4A4F58"}) + l(`M${cx},${cy} L${cx},${cy-16} M${cx},${cy} L${cx+12},${cy+6}`,{s:"#17181B",w:3}) + [0,3,6,9].map(i=>{ const a=(i*30-90)*Math.PI/180; return l(`M${(cx+19*Math.cos(a)).toFixed(1)},${(cy+19*Math.sin(a)).toFixed(1)} L${(cx+22*Math.cos(a)).toFixed(1)},${(cy+22*Math.sin(a)).toFixed(1)}`,{s:"#4A4F58",w:2}); }).join(""),
    "γιατί": (cx,cy)=> p(`M${cx},${cy-24} C${cx+22},${cy-24} ${cx+22},${cy+2} ${cx+8},${cy+10} L${cx+8},${cy+18} L${cx-8},${cy+18} L${cx-8},${cy+10} C${cx-22},${cy+2} ${cx-22},${cy-24} ${cx},${cy-24}Z`,"#FFE27A",{w:1.8,s:"#B8860B"}) + r(cx-8,cy+18,16,8,2,"#9AA3AD",{w:1.4}) + l(`M${cx-10},${cy-8} L${cx-4},${cy+2} L${cx},${cy-6} L${cx+4},${cy+2} L${cx+10},${cy-8}`,{s:"#B8860B",w:1.6}),
    "πώς": (cx,cy)=> p(`M${cx-22},${cy+20} L${cx+10},${cy-12} C${cx+4},${cy-24} ${cx+18},${cy-30} ${cx+24},${cy-24} L${cx+16},${cy-16} L${cx+22},${cy-10} L${cx+30},${cy-18} C${cx+34},${cy-8} ${cx+26},${cy+2} ${cx+14},${cy-2} L${cx-14},${cy+26}Z`,"#C9CED6",{w:1.8,s:"#4A4F58"}),
    "πόσο": (cx,cy)=> [0,1,2,3].map(i=>e(cx,cy+14-i*9,20,7,"#F2D77A",{w:1.4,s:"#8A6A12"})).join("") + txt(cx,cy-8,14,"€","#8A5A12")
  };
  const NAMES = ["τι","ποιος","πού","πότε","γιατί","πώς","πόσο"];
  const parts = NAMES.map((gr,i)=>{ const x = 6+(i%4)*106, y = 6+Math.floor(i/4)*148;
    return {gr, z:1, dot:[x+88,y+14], shapes:[ r(x,y,100,142,12,`url(#q${i})`,{w:1.8,s:"#7A8BA0"}) + ICONS[gr](x+50,y+54) + txt(x+50,y+124,24,gr) ]}; });
  const under = defs + r(0,0,436,302,0,"#FBF8EE",{w:0}) + r(6+3*106,6+148,100,142,12,"url(#q7)",{w:1.8,s:"#7A8BA0"}) + txt(6+3*106+50,6+148+96,96,"?","#C9B48A");
  return {id:"questions", name:"Question words", viewBox:"0 0 436 302", rich:true, under, parts};
})();

