/* the shared gradient of the soft light and shade (SC.lit): defined once for all the drawings */
(function(){
  const s = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  s.setAttribute("width", "0"); s.setAttribute("height", "0"); s.setAttribute("aria-hidden", "true"); s.style.cssText = "position:absolute; width:0; height:0; overflow:hidden";
  s.innerHTML = '<defs><linearGradient id="scGshade" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".26"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/><stop offset=".6" stop-color="#1a0d05" stop-opacity="0"/><stop offset="1" stop-color="#1a0d05" stop-opacity=".26"/></linearGradient></defs>';
  document.body.appendChild(s);
})();

