/* the drawing of the page "Cooking" */
const COOKING_DIAGRAMS = [SC.scope(SC_CUTLERY,"cut")];
let cookingDiagramId = "cutlery";
const renderCookingDiagram = box => renderDiagramSet(box, COOKING_DIAGRAMS, ()=>cookingDiagramId, id=>{ cookingDiagramId = id; });
